 "content": "from collections import Counter


def _runs(row):
    out = []
    i = 0
    while i < len(row):
        if row[i] == 0:
            i += 1
            continue
        j = i
        while j < len(row) and row[j] != 0:
            j += 1
        out.append((i, j))
        i = j
    return out


def transform(grid):
    h, w = len(grid), len(grid[0])
    # Tiles are separated by two-cell zero gutters; their width is the longest
    # uninterrupted nonzero run in the repeated tile rows/columns.
    tile = max((b - a for row in grid for a, b in _runs(row)), default=1)
    pitch = tile + 2
    row_starts = list(range(1, h, pitch))
    col_starts = list(range(1, w, pitch))
    centers = {}
    samples = []
    for ri, r0 in enumerate(row_starts):
        r = r0 + tile // 2
        if r >= h:
            continue
        for ci, c0 in enumerate(col_starts):
            c = c0 + tile // 2
            if c < w:
                centers[(ri, ci)] = (r, c, grid[r][c])
                samples.append(grid[r][c])
    if not samples:
        return [row[:] for row in grid]
    baseline = Counter(samples).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Match repeated non-baseline tile-center colors along each tile row/column.
    # Only zero-valued gutter cells are painted; tiles and separators stay intact.
    for ri in range(len(row_starts)):
        points = [centers[(ri, ci)] for ci in range(len(col_starts)) if (ri, ci) in centers]
        by_color = {}
        for r, c, color in points:
            if color != baseline:
                by_color.setdefault(color, []).append((r, c))
        for color, occurrences in by_color.items():
            for (_, c1), (_, c2) in zip(occurrences, occurrences[1:]):
                r = occurrences[0][0]
                for c in range(c1 + 1, c2):
                    if out[r][c] == 0:
                        out[r][c] = color

    for ci in range(len(col_starts)):
        points = [centers[(ri, ci)] for ri in range(len(row_starts)) if (ri, ci) in centers]
        by_color = {}
        for r, c, color in points:
            if color != baseline:
                by_color.setdefault(color, []).append((r, c))
        for color, occurrences in by_color.items():
            for (r1, c), (r2, _) in zip(occurrences, occurrences[1:]):
                for r in range(r1 + 1, r2):
                    if out[r][c] == 0:
                        out[r][c] = color
    return out
