def _segments(lines):
    """Return nonzero intervals along an axis, allowing zero separators."""
    spans = []
    start = None
    for i, active in enumerate(lines):
        if active and start is None:
            start = i
        elif not active and start is not None:
            spans.append((start, i))
            start = None
    if start is not None:
        spans.append((start, len(lines)))
    return spans


def transform(grid):
    h, w = len(grid), len(grid[0])
    row_spans = _segments([any(v != 0 for v in row) for row in grid])
    col_spans = _segments([any(grid[r][c] != 0 for r in range(h)) for c in range(w)])

    # The repeated tiles have a common size; edge tiles may be clipped.
    tile_h = Counter(b - a for a, b in row_spans).most_common(1)[0][0]
    tile_w = Counter(b - a for a, b in col_spans).most_common(1)[0][0]
    full_rows = [(a, b) for a, b in row_spans if b - a == tile_h]
    full_cols = [(a, b) for a, b in col_spans if b - a == tile_w]
    centers = {}
    for ri, (ra, rb) in enumerate(full_rows):
        r = (ra + rb - 1) // 2
        for ci, (ca, cb) in enumerate(full_cols):
            c = (ca + cb - 1) // 2
            centers[(ri, ci)] = (r, c, grid[r][c])

    out = [row[:] for row in grid]
    if not centers:
        return out
    common = Counter(v for r, c, v in centers.values()).most_common(1)[0][0]

    # Draw each non-default center color through intervening tiles, painting
    # only the empty separator/background cells and preserving all tile pixels.
    for ri in range(len(full_rows)):
        by_color = {}
        for ci in range(len(full_cols)):
            r, c, color = centers[(ri, ci)]
            if color != common:
                by_color.setdefault(color, []).append(c)
        r = centers[(ri, 0)][0]
        for color, positions in by_color.items():
            if len(positions) >= 2:
                for a, b in zip(positions, positions[1:]):
                    for c in range(a + 1, b):
                        if out[r][c] == 0:
                            out[r][c] = color

    for ci in range(len(full_cols)):
        by_color = {}
        for ri in range(len(full_rows)):
            r, c, color = centers[(ri, ci)]
            if color != common:
                by_color.setdefault(color, []).append(r)
        c = centers[(0, ci)][1]
        for color, positions in by_color.items():
            if len(positions) >= 2:
                for a, b in zip(positions, positions[1:]):
                    for r in range(a + 1, b):
                        if out[r][c] == 0:
                            out[r][c] = color
    return out
