 "content": "from collections import Counter


def _spans(active):
    spans, start = [], None
    for i, on in enumerate(active):
        if on and start is None:
            start = i
        elif not on and start is not None:
            spans.append((start, i))
            start = None
    if start is not None:
        spans.append((start, len(active)))
    return spans


def transform(grid):
    h, w = len(grid), len(grid[0])
    row_spans = _spans([any(v != 0 for v in row) for row in grid])
    col_spans = _spans([any(grid[r][c] != 0 for r in range(h)) for c in range(w)])
    rh = Counter(b - a for a, b in row_spans).most_common(1)[0][0]
    cw = Counter(b - a for a, b in col_spans).most_common(1)[0][0]
    rows = [(a, b) for a, b in row_spans if b - a == rh]
    cols = [(a, b) for a, b in col_spans if b - a == cw]
    if not rows or not cols:
        return [r[:] for r in grid]

    interiors = {}
    counts = Counter()
    for ri, (ra, rb) in enumerate(rows):
        for ci, (ca, cb) in enumerate(cols):
            pixels = {(r - ra, c - ca): grid[r][c]
                      for r in range(ra + 1, rb - 1)
                      for c in range(ca + 1, cb - 1)}
            interiors[ri, ci] = pixels
            counts.update(pixels.values())
    if not counts:
        return [r[:] for r in grid]
    base = counts.most_common(1)[0][0]

    masks = {}
    for key, pixels in interiors.items():
        by_color = {}
        for offset, color in pixels.items():
            if color != base:
                by_color.setdefault(color, set()).add(offset)
        masks[key] = by_color

    out = [r[:] for r in grid]
    # Repeated same-color motifs copy their complete shape through each gap.
    for ri in range(len(rows)):
        for ci1 in range(len(cols)):
            for ci2 in range(ci1 + 1, len(cols)):
                left, right = masks.get((ri, ci1), {}), masks.get((ri, ci2), {})
                for color in left.keys() & right.keys():
                    offsets = left[color] & right[color]
                    for dr, dc in offsets:
                        r = rows[ri][0] + dr
                        c = cols[ci1][0] + dc + cw
                        while c < cols[ci2][0]:
                            if out[r][c] == 0:
                                out[r][c] = color
                            c += cw

    for ci in range(len(cols)):
        for ri1 in range(len(rows)):
            for ri2 in range(ri1 + 1, len(rows)):
                top, bottom = masks.get((ri1, ci), {}), masks.get((ri2, ci), {})
                for color in top.keys() & bottom.keys():
                    offsets = top[color] & bottom[color]
                    for dr, dc in offsets:
                        r = rows[ri1][0] + dr + rh
                        c = cols[ci][0] + dc
                        while r < rows[ri2][0]:
                            if out[r][c] == 0:
                                out[r][c] = color
                            r += rh
    return out
