 "content": "from collections import Counter


def _spans(active):
    result = []
    start = None
    for i, on in enumerate(active):
        if on and start is None:
            start = i
        elif not on and start is not None:
            result.append((start, i))
            start = None
    if start is not None:
        result.append((start, len(active)))
    return result


def transform(grid):
    h, w = len(grid), len(grid[0])
    rs = _spans([any(v != 0 for v in row) for row in grid])
    cs = _spans([any(grid[r][c] != 0 for r in range(h)) for c in range(w)])
    rh = Counter(b-a for a,b in rs).most_common(1)[0][0]
    cw = Counter(b-a for a,b in cs).most_common(1)[0][0]
    rows = [(a,b) for a,b in rs if b-a == rh]
    cols = [(a,b) for a,b in cs if b-a == cw]
    if not rows or not cols:
        return [r[:] for r in grid]
    interiors = {}
    counts = Counter()
    for ri,(ra,rb) in enumerate(rows):
        for ci,(ca,cb) in enumerate(cols):
            pix={(r-ra,c-ca):grid[r][c] for r in range(ra+1,rb-1) for c in range(ca+1,cb-1)}
            interiors[ri,ci]=pix
            counts.update(pix.values())
    if not counts:
        return [r[:] for r in grid]
    base=counts.most_common(1)[0][0]
    marks={}
    for k,pix in interiors.items():
        m={}
        for off,col in pix.items():
            if col!=base:m.setdefault(col,set()).add(off)
        marks[k]=m
    out=[r[:] for r in grid]
    # Repeated motifs on a common tile row project through zero-valued gutters.
    for ri in range(len(rows)):
        for i in range(len(cols)):
            for j in range(i+1,len(cols)):
                a,b=marks.get((ri,i),{}),marks.get((ri,j),{})
                for color in a.keys() & b.keys():
                    shared=a[color] & b[color]
                    for dr,_ in shared:
                        r=rows[ri][0]+dr
                        for c in range(cols[i][1],cols[j][0]):
                            if out[r][c]==0:out[r][c]=color
    # Same operation for repeated motifs in a common tile column.
    for ci in range(len(cols)):
        for i in range(len(rows)):
            for j in range(i+1,len(rows)):
                a,b=marks.get((i,ci),{}),marks.get((j,ci),{})
                for color in a.keys() & b.keys():
                    shared=a[color] & b[color]
                    for _,dc in shared:
                        c=cols[ci][0]+dc
                        for r in range(rows[i][1],rows[j][0]):
                            if out[r][c]==0:out[r][c]=color
    return out
