    col_spans = _spans([any(grid[r][c] != 0 for r in range(h)) for c in range(w)])
    row_size = Counter(b-a for a,b in row_spans).most_common(1)[0][0]
    col_size = Counter(b-a for a,b in col_spans).most_common(1)[0][0]
    rows, cols = row_spans, col_spans
    if len(rows) < 2 or len(cols) < 2:
        return [r[:] for r in grid]

    # Infer the default interior fill from complete panels, then capture marker
    # masks from full and clipped edge panels at corresponding local offsets.
    counts = Counter()
    for ra, rb in rows:
        if rb-ra != row_size: continue
        for ca, cb in cols:
            if cb-ca != col_size: continue
            for r in range(ra+1, rb-1):
                for c in range(ca+1, cb-1): counts[grid[r][c]] += 1
    if not counts:
        return [r[:] for r in grid]
    base = counts.most_common(1)[0][0]
    markers = {}
    for ri, (ra, rb) in enumerate(rows):
        for ci, (ca, cb) in enumerate(cols):
            mask = {}
            for r in range(ra+1, min(rb, ra+row_size-1)):
                for c in range(ca+1, min(cb, ca+col_size-1)):
                    color = grid[r][c]
                    if color != base:
                        mask.setdefault(color, set()).add((r-ra, c-ca))
            markers[ri, ci] = mask

