def _period_lines(grid, vertical=False):
    n = len(grid[0]) if vertical else len(grid)
    m = len(grid) if vertical else len(grid[0])
    lines = [tuple(grid[r][c] for r in range(m)) if vertical else tuple(grid[r]) for c in range(n)] if vertical else [tuple(row) for row in grid]
    for p in range(2, n):
        if all(lines[i] == lines[i % p] for i in range(n)):
            return p
    return n


def transform(grid):
    h, w = len(grid), len(grid[0])
    ph = _period_lines(grid, vertical=False)
    pw = _period_lines(grid, vertical=True)
    if ph < 3 or pw < 3:
        return [row[:] for row in grid]
    # The repeated canvas consists of tiles separated by a two-cell zero moat.
    tile_h, tile_w = ph - 2, pw - 2
    row_starts = list(range(1, h, ph))
    col_starts = list(range(1, w, pw))
    rows = [(a, min(a + ph, h)) for a in row_starts]
    cols = [(a, min(a + pw, w)) for a in col_starts]

    interiors = {}
    frequency = Counter()
    for ri, (ra, rb) in enumerate(rows):
        for ci, (ca, cb) in enumerate(cols):
            vals = {}
            for r in range(ra + 1, min(ra + ph - 1, rb)):
                for c in range(ca + 1, min(ca + pw - 1, cb)):
                    vals[(r - ra, c - ca)] = grid[r][c]
            interiors[ri, ci] = vals
            frequency.update(vals.values())
    if not frequency:
        return [row[:] for row in grid]
    base = frequency.most_common(1)[0][0]
    markers = {}
    for key, vals in interiors.items():
        colors = {}
        for off, color in vals.items():
            if color != base:
                colors.setdefault(color, set()).add(off)
        markers[key] = colors

    out = [row[:] for row in grid]
    for ri, (ra, rb) in enumerate(rows):
        for ci1 in range(len(cols)):
            for ci2 in range(ci1 + 1, len(cols)):
                left, right = markers.get((ri, ci1), {}), markers.get((ri, ci2), {})
                for color in left.keys() & right.keys():
                    for dr, _ in left[color] & right[color]:
                        r = ra + dr
                        for c in range(cols[ci1][1], cols[ci2][0]):
                            if out[r][c] == 0:
                                out[r][c] = color
    for ci, (ca, cb) in enumerate(cols):
        for ri1 in range(len(rows)):
