def transform(grid):
    """Project matching colored interior pixels across repeated panel gutters."""
    h, w = len(grid), len(grid[0])
    # The panels recur every seven cells; blank two-cell gutters separate 5x5
    # framed panels. The last row/column may contain a clipped panel edge.
    pitch, frame = 7, 5
    row_starts = list(range(1, h, pitch))
    col_starts = list(range(1, w, pitch))
    panels = {}
    colors = Counter()
    for ri, r0 in enumerate(row_starts):
        for ci, c0 in enumerate(col_starts):
            interior = {}
            for dr in range(1, frame - 1):
                for dc in range(1, frame - 1):
                    r, c = r0 + dr, c0 + dc
                    if r < h and c < w:
                        interior[dr, dc] = grid[r][c]
                        colors[grid[r][c]] += 1
            panels[ri, ci] = interior
    if not colors:
        return [row[:] for row in grid]
    background = colors.most_common(1)[0][0]
    out = [row[:] for row in grid]

    # For each shared panel row, matching colored cells at the same local row
    # extend through zero gutters between their source panels.
    for ri, r0 in enumerate(row_starts):
        for ci1 in range(len(col_starts)):
            for ci2 in range(ci1 + 1, len(col_starts)):
                a, b = panels[ri, ci1], panels[ri, ci2]
                for dr in range(1, frame - 1):
                    for color in set(a.values()) & set(b.values()):
                        if a.get((dr, 1)) != color and a.get((dr, 2)) != color and a.get((dr, 3)) != color:
                            continue
                        for dc in range(1, frame - 1):
                            if a.get((dr, dc)) == color and b.get((dr, dc)) == color:
