    h, w = len(grid), len(grid[0])
    pitch, frame = 7, 5
    row_starts = list(range(1, h, pitch))
    col_starts = list(range(1, w, pitch))
    tiles = {}
    counts = Counter()
    for ri, r0 in enumerate(row_starts):
        for ci, c0 in enumerate(col_starts):
            vals = {}
            for dr in range(1, frame - 1):
                for dc in range(1, frame - 1):
                    r, c = r0 + dr, c0 + dc
                    if r < h and c < w:
                        vals[dr, dc] = grid[r][c]
                        counts[grid[r][c]] += 1
            tiles[ri, ci] = vals
    background = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]

    for ri, r0 in enumerate(row_starts):
        for c1 in range(len(col_starts)):
            for c2 in range(c1 + 1, len(col_starts)):
                a, b = tiles[ri, c1], tiles[ri, c2]
                common = set(a) & set(b)
                for pos in common:
                    color = a[pos]
                    if color == background or b[pos] != color:
                        continue
                    dr, dc = pos
                    r = r0 + dr
                    for c in range(col_starts[c1] + frame, col_starts[c2]):
                        if 0 <= r < h and out[r][c] == 0:
